let preparationOpen=false,preparePreview=null,runBaseline=null,overviewPaused=false,guideKey='',guideUntil=0;const lessons=new Set();let mode='chapter',lab=false,credits=0,bindings={left:'KeyA',right:'KeyD',slot1:'Digit1',slot2:'Digit2',shield:'KeyQ',magnet:'KeyE',conveyor:'KeyR',pause:'KeyP',fire:'Space',aimUp:'ArrowUp',aimDown:'ArrowDown',aimLeft:'KeyZ',aimRight:'KeyX'},settings={controlMode:'flow',assistVersion:1,autoFire:true,music:.16,effects:.45,devices:.12,voice:.35,aim:true,touchRelease:true,holdFire:true,smartWeapon:true};let characterId='player',runSerial=0,shownDraftWave=0,checkpoint=null,resumeCandidate=null;let records={};try{const saved=JSON.parse(localStorage.getItem(store)||'{}');checkpoint=saved.checkpoint||null;resumeCandidate=Game.restoreCheckpoint(checkpoint);if(!resumeCandidate)checkpoint=null;runSerial=Number.isSafeInteger(saved.runSerial)?Math.max(0,saved.runSerial):0;credits=Number.isFinite(saved.credits)?Math.max(0,saved.credits):0;settings={...settings,...saved.settings};if(saved.settings?.assistVersion!==1){settings.controlMode='flow';settings.autoFire=true;settings.assistVersion=1;}bindings={...bindings,...saved.bindings};records=saved.records&&typeof saved.records==='object'?saved.records:{};soundOn=saved.sound!==false;if(window.SignalBreakerActors.characters.some(c=>c.id===saved.characterId))characterId=saved.characterId;}catch{}
