function setupStage(id,immediate=false,retrySeed=null){tuningDock.hidden=true;shownDraftWave=0;closeView=false;overviewPaused=false;document.body.classList.remove('overview-open');$('viewBtn').textContent=t('breaker.session.overview');$('viewBtn').setAttribute('aria-pressed','false');clearInput();soundDirector.setSession(false,soundOn);const premiumRun=mode==='chapter'&&!lab,seed=retrySeed??(premiumRun?20261010+(++runSerial)*7919:20261010);if(premiumRun&&retrySeed===null){checkpoint=null;safeSave();}game=new Game(id,seed,{lab,extended:mode==='chapter',premiumRun});runBaseline=game.premiumRun?(records[id]?.bestPremium?{best:records[id].bestPremium}:null):game.extended?(records[id]?.bestFlow?{best:records[id].bestFlow}:null):(records[id]||null);guideKey='';guideUntil=0;previewCache=null;previewKey='';previewAt=0;milestones.clear();premium.reset();if(id==='SB-01')game.setAim(480,210);finishedShown=false;const c=game.config;$('missionTitle').textContent=c.name;$('missionDesc').textContent=c.summary;$('stageCode').innerHTML=c.id+' <i>'+c.name+'</i>';$('total').textContent=game.waveCount;setWeapon(game.loadout[0]);updateStageList();if(immediate){game.start();hideOverlay();toast(t('breaker.brand.promise'),2);}else showOverlay('ready');hud();}
