function quickRetry(){const seed=game.seed,id=game.config.id,loadout=[...game.loadout],level=game.weaponLevel,upgrade=game.weaponUpgrade;setupStage(id,false,seed);game.setLoadout(loadout,level,upgrade);setWeapon(loadout[0]);game.start();hideOverlay();}
