window.addEventListener('keydown',e=>{if(e.target?.matches?.('select,input,textarea')||e.repeat)return;const key=e.code;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space',bindings.fire].includes(key))e.preventDefault();keys.add(key);if(key===bindings.aimLeft||key===bindings.aimRight){manualAimUntil=game.time+1.5;const d=game.launchGeometry().direction;game.setAimElevation(Math.atan2(-d.y,Math.abs(d.x)),key===bindings.aimLeft?-1:1);}if(key===bindings.slot1)setWeapon(game.loadout[0]);if(key===bindings.slot2)setWeapon(game.loadout[1]);if(key===bindings.shield)game.cycleShield();if(key===bindings.magnet)game.toggleMagnet();if(key===bindings.pause)pause();if(key===bindings.conveyor)game.cycleConveyor();if(key==='Escape'&&game.state==='playing')pause();if(key===bindings.fire||key==='KeyF'&&!Object.values(bindings).includes('KeyF')){if(game.state==='ready'){game.start();hideOverlay();}game.fire();}if(key==='Enter'&&!Object.values(bindings).includes('Enter')&&game.state==='ready'){game.start();hideOverlay();}});
