function finalize(){if(finishedShown||!['won','lost'].includes(game.state))return;finishedShown=true;checkpoint=null;toastExpires=0;$('toast').classList.remove('visible');if(game.state==='won'&&!lab){const prev=records[game.config.id]||{};const index=CHAPTER.findIndex(c=>c.id===game.config.id),reward=window.SignalBreakerChapter.chapterReward(game.config.id,!!prev.won,game.bestChain,lab);credits+=reward;game.lastReward=reward;game.lastRewardDetails=window.SignalBreakerChapter.chapterRewardDetails(game.config.id,!!prev.won,game.bestChain,lab);records[game.config.id]={...prev,won:true,credit:Math.max(prev.credit||0,reward),best:Math.max(game.score,prev.best||0),bestChain:Math.max(game.bestChain,prev.bestChain||0),bestTime:prev.bestTime>0?Math.min(prev.bestTime,game.time):game.time,...(game.premiumRun?{bestPremium:Math.max(game.score,prev.bestPremium||0),bestPremiumTime:prev.bestPremiumTime>0?Math.min(prev.bestPremiumTime,game.time):game.time,lastPremium:{controlMode:settings.controlMode,seed:game.seed,tunings:[...game.tunings],reflectedHits:game.reflectedHits,stableCaptures:game.stableCaptures,waves:game.waveHistory.map(v=>({...v}))}}:game.extended?{bestFlow:Math.max(game.score,prev.bestFlow||0),bestFlowTime:prev.bestFlowTime>0?Math.min(prev.bestFlowTime,game.time):game.time}:{})};safeSave();updateStageList();}showOverlay(game.state);if(game.state==='lost')safeSave();}
function tick(now){const delta=last?Math.min(.05,(now-last)/1000):0;last=now;frame++;premium.update(['paused','ready'].includes(game.state)?0:delta);if(game.state==='playing'){const d=(keys.has(bindings.left)||keys.has('ArrowLeft')&&!Object.values(bindings).includes('ArrowLeft')?-1:0)+(keys.has(bindings.right)||keys.has('ArrowRight')&&!Object.values(bindings).includes('ArrowRight')?1:0);game.move(touchMove||d,delta,false,settings.controlMode!=='precision');const elevation=(keys.has(bindings.aimDown)?1:0)-(keys.has(bindings.aimUp)?1:0);if(elevation){manualAimUntil=game.time+1.5;game.adjustAimElevation(elevation,delta);}game.update(delta);if(settings.controlMode==='flow'&&game.state==='playing'){const direct=aimPadPointer!==null||game.time<manualAimUntil;if(!direct&&game.time>=assistAt){assistTarget=game.assistAim(settings.smartWeapon);assistAt=game.time+.12;setWeapon(game.weapon);}if(settings.autoFire&&(direct||assistTarget?.aligned))game.fire();}if((settings.holdFire&&aimPointer!==null)||firePointer!==null||keys.has(bindings.fire))assistedFire();}sounds();if(game.state==='intermission'&&shownDraftWave!==game.wave){shownDraftWave=game.wave;showTuning();}if(game.state==='won'||game.state==='lost')finalize();if(now>toastExpires)$('toast').classList.remove('visible');draw();drawRadar();if(preparationOpen&&preparePreview?.isConnected&&!$('overlay').classList.contains('hidden')&&premium.actor?.status().ready){const paint=preparePreview.getContext('2d');paint.setTransform(2,0,0,2,0,0);paint.clearRect(0,0,350,180);paint.save();paint.translate(150-game.player.x*1.4,172-(game.player.y+31)*1.4);paint.scale(1.4,1.4);premium.actor.draw(paint,game.player,game.player.x,game.player.y+31,game.time,game.player.life,game.weapon,game.launchGeometry());paint.restore();}if(frame%4===0)hud();requestAnimationFrame(tick);}

